const source = $('Execute Workflow Trigger').item.json || {};
const msg = source.message || source.body?.message || source.payload?.message || {};
const chatId = source.chatId || msg.chat?.id || source.payload?.chatId || source.body?.chatId || '';
const owner = String($env.OWNER_DISPLAY_NAME || 'User').trim();

const text = [
  `Mia hỗ trợ GitHub cho ${owner} ở cả hai nhóm việc: đọc repo và ghi có xác nhận.`,
  '- Đọc: xem repo, liệt kê repo trong account, tìm repo theo topic/ngôn ngữ, liệt kê branch, commit, release, PR, issue, đọc file, tìm code và xem diff.',
  '- Ghi sau khi xác nhận: tạo issue, cập nhật issue, comment issue/PR, tạo branch, cập nhật file, tạo pull request, rerun workflow lỗi.',
  '',
  `${owner} có thể thử mấy câu như:`,
  '- xem repo của mình trên GitHub',
  '- tìm repo theo topic paddleocr',
  '- xem repo octocat/Hello-World',
  '- xem cấu trúc repo octocat/Hello-World',
  '- xem branch octocat/Hello-World',
  '- xem commit octocat/Hello-World',
  '- doc file README trong repo octocat/Hello-World',
  '- tìm code Session trong repo psf/requests',
  '- tạo issue bug cho repo octocat/Hello-World',
  '- tạo branch fix/login-flow từ commit abc123 trong repo owner/repo',
  '- tạo pull request từ branch feature/a sang main trong repo owner/repo',
].join('\n');

return [{ json: { chatId, text } }];
